  "data": {
    "url": "https://gicentre.github.io/data/tests/timeTest.tsv"
  },
  "encoding": {
    "x": {
      "field": "date",
      "timeUnit": "quarter",
      "type": "temporal"
    },
    "y": {
      "aggregate": "mean",
      "field": "temperature",
      "type": "quantitative"
    }
  },
  "layer": [
    {
      "mark": {
        "type": "line",
        "color": "#FF9900",
